    for (int i = 0; i < string.length(); i++) {
        char c = string.charAt(i);
        if (c == '_') {
            upperCaseNext = true;
        } else if (upperCaseNext) {
            result.append(Character.toUpperCase(c));
            upperCaseNext = false;
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

