import java.beans.Introspector;
import java.beans.PropertyDescriptor;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;

import org.springframework.beans.BeanWrapperImpl;
import org.springframework.util.Assert;

public final class BeanMerger {

	private BeanMerger() {
	}

	public static <I, T, S extends T> T mergeBeans(S source, T target, Class<I> sourceInterfaceClazz) {
		Assert.notNull(source, "Source must not be null");
		Assert.notNull(target, "Target must not be null");
		Assert.notNull(sourceInterfaceClazz, "Source interface class must not be null");

		BeanWrapperImpl sourceWrapper = new BeanWrapperImpl(source);
		BeanWrapperImpl targetWrapper = new BeanWrapperImpl(target);

		Set<String> interfaceGetterNames = new HashSet<>();
		for (Method method : sourceInterfaceClazz.getMethods()) {
			if (isGetter(method)) {
				interfaceGetterNames.add(method.getName());
			}
		}

		for (PropertyDescriptor propertyDescriptor : sourceWrapper.getPropertyDescriptors()) {
			Method readMethod = propertyDescriptor.getReadMethod();
			if (readMethod == null || !interfaceGetterNames.contains(readMethod.getName())) {
				continue;
			}

			String propertyName = propertyDescriptor.getName();
			if (!targetWrapper.isWritableProperty(propertyName)) {
				continue;
			}

			Object value = sourceWrapper.getPropertyValue(propertyName);
			if (value != null) {
				targetWrapper.setPropertyValue(propertyName, value);
			}
		}

		return target;
	}

	private static boolean isGetter(Method method) {
		if (method.getParameterCount() != 0 || method.getReturnType() == void.class
				|| method.isBridge() || method.isSynthetic()) {
			return false;
		}

		String methodName = method.getName();
		if (methodName.startsWith("get") && methodName.length() > 3) {
			return true;
		}

		return methodName.startsWith("is") && methodName.length() > 2
				&& (method.getReturnType() == boolean.class || method.getReturnType() == Boolean.class);
	}

}

